package cn.iocoder.yudao.module.zsjos.service.review;
import cn.iocoder.yudao.module.system.api.dept.DeptApi; import cn.iocoder.yudao.module.system.api.dept.dto.DeptRespDTO; import cn.iocoder.yudao.module.system.api.user.AdminUserApi; import cn.iocoder.yudao.module.system.api.user.dto.AdminUserRespDTO; import cn.iocoder.yudao.module.zsjos.dal.dataobject.review.ReviewReportDO; import cn.iocoder.yudao.module.zsjos.dal.mysql.review.ReviewReportMapper; import cn.iocoder.yudao.module.zsjos.service.media.MediaWorkflowEventService; import org.junit.jupiter.api.Test; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import static org.junit.jupiter.api.Assertions.assertThrows; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class ReviewReportServiceTest { @InjectMocks ReviewReportService service; @Mock ReviewReportMapper mapper; @Mock AdminUserApi adminUserApi; @Mock DeptApi deptApi; @Mock MediaWorkflowEventService events;
 @Test void submitCreatesSupervisorTaskAndMessage(){ReviewReportDO row=new ReviewReportDO();row.setId(1L);row.setReviewNo("RV-1");row.setAuthorUserId(10L);row.setStatus("draft");row.setVersion(0);when(mapper.selectById(1L)).thenReturn(row);AdminUserRespDTO author=new AdminUserRespDTO();author.setId(10L);author.setDeptId(20L);when(adminUserApi.getUser(10L)).thenReturn(author);DeptRespDTO dept=new DeptRespDTO();dept.setLeaderUserId(30L);when(deptApi.getDept(20L)).thenReturn(dept);AdminUserRespDTO supervisor=new AdminUserRespDTO();supervisor.setId(30L);supervisor.setStatus(0);when(adminUserApi.getUser(30L)).thenReturn(supervisor);when(mapper.transition(1L,0,"draft","submitted")).thenReturn(1);service.submit(1L,0,10L);verify(events).createTaskAndNotify(eq("media.review.pending"),eq("MEDIA_REVIEW_APPROVAL"),eq("media-review"),eq(1L),eq(30L),anyString(),eq("review"),eq(10L),eq("media-review-approval:1:0"),anyMap());}
 @Test void missingSupervisorDoesNotAdvance(){ReviewReportDO row=new ReviewReportDO();row.setId(1L);row.setAuthorUserId(10L);row.setStatus("draft");when(mapper.selectById(1L)).thenReturn(row);when(adminUserApi.getUser(10L)).thenReturn(new AdminUserRespDTO());assertThrows(RuntimeException.class,()->service.submit(1L,0,10L));verify(mapper,never()).transition(anyLong(),anyInt(),anyString(),anyString());verifyNoInteractions(events);}
 @Test void rejectNotifiesAuthor(){ReviewReportDO row=new ReviewReportDO();row.setId(1L);row.setReviewNo("RV-1");row.setAuthorUserId(10L);row.setReviewerUserId(30L);row.setStatus("submitted");when(mapper.selectById(1L)).thenReturn(row);when(mapper.transition(1L,2,"submitted","rejected")).thenReturn(1);service.reject(1L,2,"补充证据",30L);verify(events).notify(eq("media.review.rejected"),eq("media-review"),eq(1L),eq(10L),eq(30L),eq("media-review-result:1:2:rejected"),anyMap());}
}
